(x, y, t) => {
  const cx = 240, cy = 120;
  let wx = Math.sin(x*0.015+t*0.2)*20+Math.cos(y*0.012-t*0.15)*15;
  let wy = Math.cos(y*0.015-t*0.18)*20+Math.sin(x*0.013+t*0.22)*15;
  const wx2 = Math.sin((x+wx)*0.02+t*0.3)*12+Math.cos((y+wy)*0.018-t*0.25)*8;
  const wy2 = Math.cos((y+wy)*0.02-t*0.28)*12+Math.sin((x+wx)*0.016+t*0.32)*8;
  const sx = x+wx+wx2, sy = y+wy+wy2;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,1.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,0.9],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,1.1],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,0.85],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,1.05],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,0.95],
    [80+Math.sin(t*0.45+3)*60,40+Math.cos(t*0.65+1)*40,0.14,1.3,0.8],
    [400+Math.cos(t*0.55+2)*70,200+Math.sin(t*0.75+4)*50,0.11,1.8,1.0],
    [200+Math.sin(t*0.25+5)*100,220+Math.cos(t*0.45+3)*60,0.05,2.8,1.15]
  ];
  let aS=0,iS=0,iS2=0;
  for(const[sX,sY,f,sp,w]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp)*w;iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    iS2+=Math.sin(d*f*0.5-t*sp*0.4+3.0)*w;
  }
  const act=aS/9,inh=iS/9,inh2=iS2/9;
  const bg1=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2;
  const bg2=Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const bg3=Math.sin(sx*0.07-t*1.5)*Math.sin(sy*0.06+t*1.2)*0.3;
  const bg=bg1+bg2+bg3;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const radial=Math.sin(dist*0.08-t*2.0)*Math.cos(ang*2+t*0.5)*0.25;
  const flow=Math.sin(sx*0.03+Math.sin(sy*0.04+t)*2+t*0.5)*Math.cos(sy*0.03+Math.cos(sx*0.05-t)*1.5-t*0.3)*0.35;
  const reaction=Math.tanh((act-inh*0.6-inh2*0.3+bg*0.25+spiral+radial+flow)*2.0);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5+Math.sin((sx-sy)*0.08-t*0.7)*0.3)*1.5)*0.3;
  const micro=(Math.sin(sx*0.4+sy*0.3+t*3)*Math.sin(sx*0.35-sy*0.25-t*2.5))*0.1;
  const blend=reaction*0.6+cell*0.2+micro*0.1+flow*0.1,v=blend*0.5+0.5;
  const pal=[[6,12,52],[12,45,95],[18,85,120],[25,135,130],[60,170,120],[160,195,80],[220,200,65],[235,160,55],[225,110,60],[195,65,55],[150,35,65],[90,20,55],[45,15,50],[6,12,52]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i,sf=f*f*(3-2*f);
  const lum=0.85+Math.sin(reaction*Math.PI)*0.15,absR=Math.abs(reaction);
  const edge=absR>0.75?1.0+(absR-0.75)*0.8:1.0,glow=Math.max(0,absR-0.85)*3.0;
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*sf)*lum*edge+glow*40)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*sf)*lum*edge+glow*25)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*sf)*lum*edge+glow*15)|0)
  ];
}
